
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_lambda_ch_n_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_lambda_ch_n", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.303108915039046e+00, -4.221374854495837e+00, -4.106953281994051e+00, -3.948676290875043e+00, -3.733476466157048e+00, -3.448051468329441e+00, -3.082724292576551e+00, -2.638221123853494e+00, -2.133787095384063e+00, -1.606065426737084e+00, -1.082854480118244e+00, -7.088050710681765e-01, -6.020914967549138e-01, -5.011626588322109e-01, -3.698537343690974e-01, -2.413577625040897e-01, -1.312098438897976e-01, -4.833539723157045e-02, -1.053733102159213e-02, -1.185222992042849e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


